"""
Kafka Topics

Central place to define all Kafka topic names
used by the AI SaaS Product Analytics Platform.
"""

# ==========================================================
# Main Streaming Topics
# ==========================================================

# Raw AI SaaS events generated by the simulator
AI_PRODUCT_EVENTS = "ai-product-events"

# ==========================================================
# Future Topics
# ==========================================================

# Dead Letter Queue
# Stores invalid or failed events for later inspection.
AI_PRODUCT_EVENTS_DLQ = "ai-product-events-dlq"

# Bronze Layer Events
# Used if the Bronze layer republishes events.
BRONZE_EVENTS = "bronze-events"

# Silver Layer Events
# Used for cleaned and validated events.
SILVER_EVENTS = "silver-events"

# Gold Layer Events
# Used for business-ready analytics.
GOLD_EVENTS = "gold-events"

# ==========================================================
# Helper
# ==========================================================

ALL_TOPICS = [
    AI_PRODUCT_EVENTS,
    AI_PRODUCT_EVENTS_DLQ,
    BRONZE_EVENTS,
    SILVER_EVENTS,
    GOLD_EVENTS,
]


if __name__ == "__main__":

    print("Kafka Topics")

    for topic in ALL_TOPICS:
        print(f"• {topic}")